export default function renderFilteredTree(root, needle) {
  if (!root) return '';
  if (needle && root.value.includes(needle)) return '';
  const lines = [];
  const walk = (node, depth) => {
    lines.push(`${'  '.repeat(depth)}${node.value}`);
    for (const child of node.children || []) {
      if (needle && child.value.includes(needle)) continue;
      walk(child, depth + 1);
    }
  };
  walk(root, 0);
  return lines.join('\n');
}

