export default function renderFilteredTree(root, needle) {
  if (!root || (needle && root.value.includes(needle))) return '';
  const lines = [];
  const stack = [{ node: root, depth: 0 }];
  while (stack.length) {
    const { node, depth } = stack.pop();
    lines.push(`${'  '.repeat(depth)}${node.value}`);
    const children = node.children || [];
    for (let i = children.length - 1; i >= 0; i -= 1) {
      const child = children[i];
      if (needle && child.value.includes(needle)) continue;
      stack.push({ node: child, depth: depth + 1 });
    }
  }
  return lines.join('\n');
}
